pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize the pool with a non-ETH base token (e.g., address(1)) and no merkle root.
        address _baseToken = address(1);
        address _nft = address(2);
        uint128 _virtualBaseTokenReserves = 1000 ether;
        uint128 _virtualNftReserves = 10 ether;
        uint56 _changeFee = 0;
        uint16 _feeRate = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        // After initialization, check baseToken: reference sets it to _baseToken (address(1)),
        // mutant sets it to address(0).
        // Now attempt a buy() with msg.value > 0, which should revert because baseToken != address(0).
        // The buy requires token IDs and weights; since merkleRoot is zero, any weight works.
        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = 1;
        uint256[] memory tokenWeights = new uint256[](1);
        tokenWeights[0] = 1e18;
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        // Fund this contract with ETH for the test.
        vm.deal(address(this), 1 ether);

        // Call buy with msg.value > 0.
        // In reference (baseToken = address(1)), the check "baseToken != address(0) && msg.value > 0" reverts.
        // In mutant (baseToken = address(0)), the check passes and buy would proceed (fails later for other reasons, but the point is the revert differs).
        bool reverted;
        try c.buy{value: 1 ether}(tokenIds, tokenWeights, proof) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The reference should revert (reverted == true), the mutant might not (reverted == false).
        // Since the mutant incorrectly sets baseToken to address(0), it does not revert, so we assert that the reference reverts.
        assertTrue(reverted);
    }
}

